// Generated texture assets for AGO WORLD BOX (paper-style tiles). Enemy uses the official /img/jinrou.png.
// Masters: ~/workspace/ago-world-box/assets-final/*.png — regenerate this file if they change.
export const TEXTURE_DATA: Record<string, string> = {
  grass: "data:image/png;base64,",
  dirt: "data:image/png;base64,",
  stone: "data:image/png;base64,",
  bedrock: "data:image/png;base64,",
  wood: "data:image/png;base64,",
  leaves: "data:image/png;base64,",
  coal: "data:image/png;base64,",
  copper: "data:image/png;base64,",
  sand: "data:image/png;base64,",
  water: "data:image/png;base64,",
};

// Discord ダンジョンのタイル素材（64×64 ピクセルアート）をそのまま流用する。
// 実体は web/public/img/worldbox/ に置き、アバターと同じ画像読み込みで使う。
export const DUNGEON_TILE_SRC: Record<string, string> = {
  grass: "/img/worldbox/grass.png",
  dirt: "/img/worldbox/dirt.png",
  tree: "/img/worldbox/tree.png",
  rock: "/img/worldbox/rock.png",
  snow: "/img/worldbox/snow.png",
  snowTree: "/img/worldbox/snow-tree.png",
};

export function loadDungeonTiles(): Record<string, HTMLImageElement> {
  const out: Record<string, HTMLImageElement> = {};
  for (const [k, v] of Object.entries(DUNGEON_TILE_SRC)) { const img = new Image(); img.src = v; out[k] = img; }
  return out;
}

export function loadTextures(): Record<string, HTMLImageElement> {
  const out: Record<string, HTMLImageElement> = {};
  for (const [k, v] of Object.entries(TEXTURE_DATA)) { const img = new Image(); img.src = v; out[k] = img; }
  return out;
}

